		d[s] = 0;
		while (qh != qt) {
			// cout<<qh<<" "<<qt<<"  ";
			ll v = q[qh++];
			id[v] = 2;
			if (qh == n)  qh = 0;
			for (size_t i=0; i<g[v].size(); ++i) {
				rib & r = g[v][i];
