#include <bits/stdc++.h>
using namespace std;
const int N = 10000,M = N * 100;
const long long inf = LLONG_MAX >> 5;
class FlowGraph
{
private:
    int head[N],v[M],nxt[M],c[M],ptr,t;
    long long w[M],cost;
    inline void padd_edge(int uu,int vv,long long ww,int cc)
    {
        v[ptr] = vv;w[ptr] = ww;c[ptr] = cc;
        nxt[ptr] = head[uu];head[uu] = ptr++;
    }
    int dis[N],id[N],cur[N];bool vis[N];
    bool spfa(int s,int t)
    {
        memset(vis,0,sizeof(vis));
        memset(dis,-1,sizeof(dis));
        queue<int> q;q.push(s);
        dis[s] = 0;id[s] = 1;
        while (!q.empty())
        {
            int nd = q.front();
			q.pop();vis[nd] = 0;
            for (int i = head[nd];i != -1;i = nxt[i])
                if (w[i] && (dis[v[i]] == -1 || dis[v[i]] > dis[nd] + c[i]))
                {
                    dis[v[i]] = dis[nd] + c[i];
                    if (!vis[v[i]])
                    {
                        vis[v[i]] = 1;q.push(v[i]);
                    }
                }
        }
        return dis[t] != -1;
    }
    long long dfs(int pos,long long flow)
    {
        if (pos == t) return flow;
        vis[pos] = 1;
        long long tmp = flow;
        for (int i = cur[pos] != -1 ? cur[pos] : head[pos];i != -1;i = nxt[i])
            if (!vis[v[i]] && w[i] && dis[v[i]] == dis[pos] + c[i])
            {
                cur[pos] = i;
                long long fl = dfs(v[i],min(flow,w[i]));
                cost += fl * c[i];
                w[i] -= fl;w[i ^ 1] += fl;
                flow -= fl;
                if (!flow) break;
            }
        return tmp - flow;
    }
public:
    FlowGraph()
    {memset(head,-1,sizeof(head));memset(nxt,-1,sizeof(nxt));}
    inline void add_edge(int uu,int vv,long long ww,int cc)
    {
        padd_edge(uu,vv,ww,cc);padd_edge(vv,uu,0,-cc);
    }
    long long dinic(int s,int t)
    {
        cost = 0;this->t = t;
        while (spfa(s,t)) 
        {
            memset(cur,-1,sizeof(cur));dfs(s,inf);
        }
        return cost;
    }
};
FlowGraph g;
int n,m,kk,c,d,a[55];
int main ()
{
    ios::sync_with_stdio(false);
    cin >> n >> m >> kk >> c >> d;
    for (int i = 1;i <= kk;i++) cin >> a[i];
    int s = 0,t = n * 100 + 1;
    for (int i = 1;i <= 100;i++) g.add_edge(i,t,inf,0);
    for (int i = 1;i <= kk;i++) g.add_edge(s,(a[i] - 1) * 100 + 1,1,0);
    for (int i = 2;i <= n;i++)
        for (int j = 1;j < 100;j++)
            g.add_edge((i - 1) * 100 + j,(i - 1) * 100 + j + 1,inf,c);
    int t1,t2;
    for (int _ = 1;_ <= m;_++)
    {
        cin >> t1 >> t2;
        for (int i = 1;i < 100;i++)
            for (int j = 1;j <= kk;j++) //其实不用枚举到kk，枚举到25左右即可
            {
                int val = c + d * (j * j - (j - 1) * (j - 1));
                g.add_edge((t1 - 1) * 100 + i,(t2 - 1) * 100 + i + 1,1,val);
                g.add_edge((t2 - 1) * 100 + i,(t1 - 1) * 100 + i + 1,1,val);
            }
    }
    cout << g.dinic(s,t) << endl;
    return 0;
}
// 最小费用流 珂以利用流量来处理多人走同一条路的情况

#include<bits/stdc++.h>
using namespace std;
#define Fopen freopen("_in.txt","r",stdin); freopen("_out.txt","w",stdout);
#define LL long long
#define ULL unsigned LL
#define fi first
#define se second
#define pb push_back
#define lson l,m,rt<<1
#define rson m+1,r,rt<<1|1
#define lch(x) tr[x].son[0]
#define rch(x) tr[x].son[1]
#define max3(a,b,c) max(a,max(b,c))
#define min3(a,b,c) min(a,min(b,c))
typedef pair<int,int> pll;
const int inf = 0x3f3f3f3f;
const int _inf = 0xc0c0c0c0;
const LL INF = 0x3f3f3f3f3f3f3f3f;
const LL _INF = 0xc0c0c0c0c0c0c0c0;
const LL mod =  (int)1e9+7;
const int Z = 100;
const int N = Z * Z;
const int M = Z * Z * Z * 3;
int px[N], py[N];
int head[N], to[M], ct[M], w[M], nt[M];
int d[N], vis[N];
int pre[N], id[N];
int s, t, tot;

void add(int u, int v, int flow, int cost){
    to[tot] = v; ct[tot] = cost;
    w[tot] = flow; nt[tot] = head[u]; head[u] = tot++;

    to[tot] = u; ct[tot] = -cost;
    w[tot] = 0; nt[tot] = head[v]; head[v] = tot++;
}
void init(){
    memset(head, -1, sizeof(head));
    tot = 0;
}
int spfa(int s, int t){
    queue<int> q;
    memset(d, inf, sizeof(d));
    memset(vis, 0, sizeof(vis));
    memset(pre, -1, sizeof(pre));
    d[s] = 0;
    q.push(s);
    while(!q.empty()){
        int u = q.front(); q.pop();
        vis[u] = 0;
//        cout << u << " " << d[u] << endl;
        for(int i = head[u]; ~i; i = nt[i]){
            if(w[i] > 0 && d[to[i]] > d[u] + ct[i]){
                d[to[i]] = d[u] + ct[i];
                pre[to[i]] = u;
                id[to[i]] = i;
//                if(to[i] == 201) cout << "Updata " << u << " " << to[i] <<" " << d[to[i]] <<endl;
                if(!vis[to[i]]){
                    vis[to[i]] = 1;
                    q.push(to[i]);
                }
            }
        }

    }
//    cout << d[t] << "? "<< endl;
    return d[t] < inf;
}
int MaxFlow(int s, int t){
    int Mi = inf;
    int sum = 0;
    int tt = 0;
//    cout << s << " ss " << t  << endl;
    while(spfa(s, t)){
        Mi = inf;
        for(int i = t; i != s; i = pre[i])
            Mi = min(Mi, w[id[i]]);
        for(int i = t; i != s; i = pre[i]){
            w[id[i]] -= Mi;
            w[id[i]^1] += Mi;
        }
        tt += Mi;
        sum += d[t] * Mi;
//        cout << d[t] << endl;
//        cout << "asd" << endl;
    }
    return sum;
}
