            self.min_cost += self.ptnl[dst] * resid
            node = dst
            while node != src:
                e = self.last[node]
                e.cap -= resid
                e.rev.cap += resid
                node = e.src
        return True

    def optimal(self):
        self.solve()
        return self.min_cost

