queue<int >Q;
void jb(int x,int y,int z,int v){
	ne[++tot]=fi[x];
	fi[x]=tot;
	zz[tot]=y;
	sl[tot]=z;
	w[tot]=v;
	ne[++tot]=fi[y];
	fi[y]=tot;
	zz[tot]=x;
	sl[tot]=0;
	w[tot]=-v;
}
int bfs(){
	Q.push(S);
	memset(dis,0x3f3f3f3f,sizeof dis);
	dis[S]=0;
	while (!Q.empty()){
		int now=Q.front();Q.pop();flag[now]=0;
		for (int i=fi[now];i;i=ne[i])
			if (sl[i]&&dis[zz[i]]>dis[now]+w[i]){
				dis[zz[i]]=dis[now]+w[i];
				if (!flag[zz[i]]){
					flag[zz[i]]=1;
					Q.push(zz[i]);
				}
			}
	}
	return dis[T]<=1e9;
}
int dfs(int x,int y){
	int s=0,b;
	flag[x]=1;
	if (x==T)return y;
	for (int &i=cur[x];i;i=ne[i])
		if (!flag[zz[i]]&&sl[i]&&dis[zz[i]]==dis[x]+w[i]&&(b=min(y,dfs(zz[i],min(y,sl[i]))))){
			sl[i]-=b;
			sl[i^1]+=b;
			s+=b;y-=b;
			if (!y)return s;
		}
	return s;	
}
