int s,t;
int dis[N],flow[N],pre[N],las[N]; bool in[N];
bool spfa ()
{
	for (int i=1; i<=t; i++)
		dis[i]=1e9,flow[i]=pre[i]=las[i]=0,in[i]=0;
	queue <int> q;
	dis[s]=0,flow[s]=1e9,q.push (s),in[s]=1;
	while (q.size ())
	{
		int u=q.front (); q.pop (); in[u]=0;
		for (int kb=top[u]; kb; kb=lb[kb].nx)
		{
			int v=lb[kb].v,w=lb[kb].w,c=lb[kb].c;
			if (w&&dis[v]> dis[u]+c)
			{
				dis[v]=dis[u]+c;
				flow[v]=min (flow[u],w);
				pre[v]=u,las[v]=kb;
				if (!in[v]) q.push (v),in[v]=1;
			}
		}
	}
	return pre[t];
}
int maflow,micost;
void mcmf ()
{
	while (spfa ())
	{
		int u=t,fl=flow[t]; maflow+=fl,micost+=fl*dis[t];
		while (u!=s)
		{
			lb[las[u]].w-=fl,lb[las[u]^1].w+=fl;
			u=pre[u];
		}
	}
}
