            cls.sz[i] = 0
            cls.adj[i] = []

    @classmethod
    def add_edge(cls, a, b, c=1, p=0):
        cls.mc = max(cls.mc, c)
        cls.adj[a].append(cls.Edge(b, cls.sz[b], 0, c, p))
        cls.sz[b] += 1
        cls.adj[b].append(cls.Edge(a, cls.sz[a], 0, 0, -p))
        cls.sz[a] += 1

    @classmethod
    def pot_init(cls, n):
        cls.pot = [0] * n
        for i in range(1, n):
            for u in range(n):
                for e in cls.adj[u]:
                    if e.c:
                        cls.pot[e.v] = min(cls.pot[e.v], cls.pot[u] + e.p)

    @classmethod
    def mcf(cls, s, t, price, n, sparse):
        vis = [False] * n
        dist = [INF] * n
        par = [-1] * n
        dist[s] = 0

        if sparse:
            # SPFA
            dk = deque([s])
            while dk:
                u = dk.popleft()
                if vis[u]:
                    continue
                vis[u] = True
                for e in cls.adj[u]:
                    if e.f < e.c and dist[e.v] > dist[u] + cls.pot[u] - cls.pot[e.v] + e.p:
                        dist[e.v] = dist[u] + cls.pot[u] - cls.pot[e.v] + e.p
                        par[e.v] = e.r
                        dk.append(e.v)
        else:
            # Dense
            u = s
            while u != -1:
                vis[u] = True
                for e in cls.adj[u]:
                    if e.f < e.c and dist[e.v] > dist[u] + cls.pot[u] - cls.pot[e.v] + e.p:
                        dist[e.v] = dist[u] + cls.pot[u] - cls.pot[e.v] + e.p
                        par[e.v] = e.r
                u = -1
                best = INF
                for i in range(n):
                    if not vis[i] and dist[i] < best:
                        best = dist[i]
                        u = i

        if dist[t] >= INF:
            return 0
        df = INF
        u = t
        while u != s:
            r = cls.adj[u][par[u]]
            r_v = r.v
            r_r = r.r
            e = cls.adj[r_v][r_r]
            df = min(df, e.c - e.f)
            u = r_v
        u = t
        while u != s:
            r = cls.adj[u][par[u]]
            r_v = r.v
            r_r = r.r
            e = cls.adj[r_v][r_r]
            e.f += df
            cls.adj[r_v][r_r ^ 1].f -= df
            price[0] += df * e.p
            u = r_v
        for i in range(n):
            cls.pot[i] = min(INF, dist[i] + cls.pot[i])
        return df

