        for (int tmp = t;tmp!=s;) {
//            if (tmp==100) {
//                cout << "xyu";
//            }
            int eid = par[tmp];
            pushed = min(pushed, edges[eid].cap-edges[eid].flow);
            sum+=edges[eid].cost;
            tmp = edges[eid].from;
        }
        flow+=pushed;
        cost+=pushed*sum;
        //cout << "flow: " << flow << ", cost: " << cost << endl <<  t << " ";
        for (int tmp=t;tmp!=s;) {
