class DisjointSet:
    def __init__(self, n):
        self.N = n
        self.P = list(range(n + 1))
        self.R = [0] * (n + 1)
        self.A = [1] * (n + 1)
    def getA(self, x):
        return self.A[x]
    def find_set(self, x):
        if self.P[x] != x:
            self.P[x] = self.find_set(self.P[x])
        return self.P[x]
    def union_set(self, x, y):
        px, py = self.find_set(x), self.find_set(y)
        if px == py:
            return px
        if self.R[px] > self.R[py]:
            self.P[py] = px
            self.A[px] += self.A[py]
            return px
        else:
            self.P[px] = py
            self.A[py] += self.A[px]
            if self.R[px] == self.R[py]:
                self.R[py] += 1
            return py

class LIS:
    def __init__(self, n):
        self.N = n
    def execute(self, A):
        v = []
        vi = -1
        for x in A:
            if not v or x > v[-1]:
                v.append(x)
                vi += 1
            else:
                lo, hi = 0, vi
                while lo < hi:
                    mid = (lo + hi) // 2
                    if v[mid] >= x:
                        hi = mid
                    else:
                        lo = mid + 1
                v[lo] = x
        return len(v)
    def execute2(self, A):
        v = []
        v1 = []
        p = [-1] * len(A)
        for i, x in enumerate(A):
            if not v or v[-1] < x:
                p[i] = v1[-1] if v1 else -1
                v.append(x)
                v1.append(i)
            else:
                import bisect
                idx = bisect.bisect_left(v, x)
                v[idx] = x
                p[i] = v1[idx - 1] if idx > 0 else -1
                v1[idx] = i
        length = len(v1)
        ret = [0] * length
        i = v1[-1]
        for j in range(length - 1, -1, -1):
            ret[j] = A[i]
            i = p[i]
        return ret
    def execute3(self, A):
        ret = 0
        v = [0] * len(A)
        for i in range(len(A)):
            for j in range(i):
                if A[j] < A[i] and v[i] < v[j]:
                    v[i] = v[j]
            v[i] += 1
            if v[i] > ret:
                ret = v[i]
        return ret

