class SegmentTree2D:
    def __init__(self, n, m):
        self.N = n
        self.M = m
        self.P = [[0] * (m + 1) for _ in range(n + 1)]
        self.T = [Point() for _ in range(n * m * 2)]
        self.build()
    def build(self):
        for i in range(1, self.N + 1):
            for j in range(1, self.M + 1):
                self.P[i][j] = 0
        self._build(1, 1, 1, self.N, self.M)
    def _build(self, node, a1, b1, a2, b2):
        if a1 > a2 or b1 > b2:
            return Point()
        if a1 == a2 and b1 == b2:
            return Point(a1, b1, self.P[a1][b1])
        self.T[node] = Point()
        self.T[node] = max(self.T[node], self._build(4 * node - 2, a1, b1, (a1 + a2) // 2, (b1 + b2) // 2))
        self.T[node] = max(self.T[node], self._build(4 * node - 1, (a1 + a2) // 2 + 1, b1, a2, (b1 + b2) // 2))
        self.T[node] = max(self.T[node], self._build(4 * node + 0, a1, (b1 + b2) // 2 + 1, (a1 + a2) // 2, b2))
        self.T[node] = max(self.T[node], self._build(4 * node + 1, (a1 + a2) // 2 + 1, (b1 + b2) // 2 + 1, a2, b2))
        return self.T[node]
    def query(self, x1, y1, x2, y2):
        return self._query(1, 1, 1, self.N, self.M, x1, y1, x2, y2)
    def _query(self, node, a1, b1, a2, b2, x1, y1, x2, y2):
        if x1 > a2 or y1 > b2 or x2 < a1 or y2 < b1 or a1 > a2 or b1 > b2:
            return Point()
        if x1 <= a1 and y1 <= b1 and a2 <= x2 and b2 <= y2:
            return self.T[node]
        mx = Point()
        mx = max(mx, self._query(4 * node - 2, a1, b1, (a1 + a2) // 2, (b1 + b2) // 2, x1, y1, x2, y2))
        mx = max(mx, self._query(4 * node - 1, (a1 + a2) // 2 + 1, b1, a2, (b1 + b2) // 2, x1, y1, x2, y2))
        mx = max(mx, self._query(4 * node + 0, a1, (b1 + b2) // 2 + 1, (a1 + a2) // 2, b2, x1, y1, x2, y2))
        mx = max(mx, self._query(4 * node + 1, (a1 + a2) // 2 + 1, (b1 + b2) // 2 + 1, a2, b2, x1, y1, x2, y2))
        return mx
    def _update(self, node, a1, b1, a2, b2, x, y, value):
        if a1 > a2 or b1 > b2:
            return Point()
        if x > a2 or y > b2 or x < a1 or y < b1:
            return self.T[node]
        if x == a1 and y == b1 and x == a2 and y == b2:
            self.T[node] = Point(x, y, value)
            return self.T[node]
        self.T[node] = max(self.T[node], self._update(4 * node - 2, a1, b1, (a1 + a2) // 2, (b1 + b2) // 2, x, y, value))
        self.T[node] = max(self.T[node], self._update(4 * node - 1, (a1 + a2) // 2 + 1, b1, a2, (b1 + b2) // 2, x, y, value))
        self.T[node] = max(self.T[node], self._update(4 * node + 0, a1, (b1 + b2) // 2 + 1, (a1 + a2) // 2, b2, x, y, value))
        self.T[node] = max(self.T[node], self._update(4 * node + 1, (a1 + a2) // 2 + 1, (b1 + b2) // 2 + 1, a2, b2, x, y, value))
        return self.T[node]
    def update(self, x, y, value):
        return self._update(1, 1, 1, self.N, self.M, x, y, value)

