import sys

def main():
    input = sys.stdin.read().strip().split()
    real_n, k = map(int, input[0:2])
    real_p = list(map(float, input[2:2+real_n]))

    n = 0
    id_list = []
    p_list = []

    for i in range(real_n):
        if real_p[i] > 1e-4:
            id_list.append(i)
            p_list.append(real_p[i])
            n += 1

    k = min(k, n)

    kb = [0] * (1 << n)
    for t in range(1, 1 << n):
        kb[t] = kb[t & (t - 1)] + 1

    f = [0.0] * (1 << n)
    ans = [0.0] * real_n

    f[0] = 1.0

    for t in range(1 << n):
        if kb[t] == k:
            for j in range(n):
                if t & (1 << j):
                    ans[id_list[j]] += f[t]
            continue
        total = 0.0
        for j in range(n):
            if t & (1 << j):
                continue
            total += p_list[j]
        if total == 0:
            continue
        q = f[t] / total
        for j in range(n):
            if t & (1 << j):
                continue
            f[t | (1 << j)] += p_list[j] * q

    print(' '.join(f"{ans[i]:.17f}" for i in range(real_n)))

