import sys

def pw(x, p, M):
    r = 1
    while p > 0:
        if p & 1:
            r = (r * x) % M
        x = (x * x) % M
        p >>= 1
    return r

class DSU:
    def __init__(self, n):
        self.r = [1] * n
        self.p = list(range(n))

    def par(self, i):
        if self.p[i] != i:
            self.p[i] = self.par(self.p[i])
        return self.p[i]

    def unite(self, i, j):
        i = self.par(i)
        j = self.par(j)
        if i == j:
            return
        if self.r[i] < self.r[j]:
            i, j = j, i
        self.p[j] = i
        self.r[i] += self.r[j]

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    k = int(input_data[1])
    mod = 10**9 + 7

    if k == 0:
        print(pw(n, n - 1, mod))
        return

    d = DSU(n)
    for i in range(n):
        d.unite(i, (i * k) % n)

    ans = 1
    for i in range(n):
        if d.par(i) != i:
            continue
        t = pw(k, d.r[i], n)
        if t == 1:
            ans = (ans * n) % mod

    print(ans)

if __name__ == "__main__":
    main()

