def modpow(b, e, MOD=10**9+7):
    ans = 1
    while e:
        if e % 2 == 1:
            ans = (ans * b) % MOD
        b = (b * b) % MOD
        e //= 2
    return ans

class DisjointSet:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rnk = [0] * n
        self.comps = n

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def merge(self, u, v):
        u = self.find(u)
        v = self.find(v)
        if u == v:
            return
        if self.rnk[u] > self.rnk[v]:
            u, v = v, u
        self.parent[u] = v
        if self.rnk[u] == self.rnk[v]:
            self.rnk[v] += 1
        self.comps -= 1

def main():
