import sys
import math

def bipow(a, b, mod):
    if b == 0:
        return 1
    ans = bipow(a, b // 2, mod)
    if b % 2 == 0:
        return (ans * ans) % mod
    else:
        return (a * (ans * ans % mod)) % mod

def doit(i, k, n, used):
    cant = 0
    while True:
        if used[i]:
            break
        used[i] = True
        i = (i * k) % n
        cant += 1
    return cant

