import sys
import math

def getbit(n, i):
    return (n & (1 << i)) != 0

def setbit0(n, i):
    return n & ~(1 << i)

def setbit1(n, i):
    return n | (1 << i)

def togglebit(n, i):
    return n ^ (1 << i)

def lastone(n):
    return n & (-n)

gap = 32

def read_int():
    c = sys.stdin.read(1)
    while c and (c < '0' or c > '9'):
        c = sys.stdin.read(1)
    x = 0
    while c and '0' <= c <= '9':
        x = x * 10 + (ord(c) & 15)
        c = sys.stdin.read(1)
    return x

# Disjoint Set Union (Union-Find) implementation
class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rating = [0] * n

    def findparent(self, root):
        while self.parent[root] != root:
            root = self.parent[root]
        return root

    def findunion(self, root1, root2):
        par1 = self.findparent(root1)
        par2 = self.findparent(root2)
        if self.rating[par1] >= self.rating[par2]:
            self.parent[par2] = par1
            self.rating[par1] += 1
        else:
            self.parent[par1] = par2
            self.rating[par2] += 1

def modularExponentiation(x, n, M):
    if n == 0:
        return 1
    elif n % 2 == 0:
        return modularExponentiation((x * x) % M, n // 2, M)
    else:
        return (x * modularExponentiation((x * x) % M, (n - 1) // 2, M)) % M

def main():
    input_data = sys.stdin.read().split()
    n = int(input_data[0])
    m = int(input_data[1])
    mod = 1000000007

    dsu = DSU(n + 1)

    if m == 0:
        print(modularExponentiation(n, n - 1, mod))
    elif m == 1:
        print(modularExponentiation(n, n, mod))
    else:
        for i in range(1, n):
            bash = (i * m) % n
            dsu.findunion(i, bash)
        s = set()
        for i in range(1, n):
            parent_i = dsu.findparent(i)
            s.add(parent_i)
        sz = len(s)
        print(modularExponentiation(n, sz, mod))

