import sys
from collections import deque
from typing import List, Tuple, Optional

# Define constants
INF = 10**9

# Data structures for flow network
class Edge:
    def __init__(self, from_node, to_node, flow):
        self.from_node = from_node
        self.to_node = to_node
        self.flow = flow
        self.opposite: Optional['Edge'] = None

class Node:
    def __init__(self):
        self.adjusted: List[Edge] = []
        self.back: Optional[Edge] = None
        self.age: int = 0

def adjust(e: Optional[Edge], d: int) -> int:
    if e is None:
        return d
    d = adjust(e.from_node.back, min(d, e.flow))
    e.flow -= d
    e.opposite.flow += d
    return d

def connect(a: Node, b: Node, w: int):
    ea = Edge(a, b, w)
    eb = Edge(b, a, 0)
    ea.opposite = eb
    eb.opposite = ea
    a.adjusted.append(ea)
    b.adjusted.append(eb)

def max_flow(g: List[Node], source: Node, sink: Node) -> int:
    result = 0
    while True:
        for u in g:
            u.age = 0
        q = deque()
        q.append(source)
        source.age = 1
        while q and sink.age == 0:
            u = q.popleft()
            for e in u.adjusted:
                v = e.to_node
                if v.age != 0 or e.flow == 0:
                    continue
                v.back = e
                v.age = u.age + 1
                q.append(v)
        if sink.age == 0:
            break
        for e in sink.adjusted:
            o = e.opposite
            if o.from_node.age != sink.age - 1 or o.flow == 0:
                continue
            result += adjust(o, o.flow)
    return result

def linear(t: int, r: int, c: int, n: int) -> int:
