class Maxflow:
    class edge:
        def __init__(self, from_, to, flow, capacity):
            self.from_ = from_
            self.to = to
            self.flow = flow
            self.capacity = capacity

    def __init__(self):
        self.edg = []
        self.g = [[] for _ in range(MAX_SIZE)]
        self.s = 0
        self.t = 0
        self.dist = [0] * MAX_SIZE
        self.visited = [0] * MAX_SIZE
        self.cur = [0] * MAX_SIZE

    def init(self):
        self.edg.clear()
        for i in range(MAX_SIZE):
            self.g[i].clear()

    def addedge(self, from_, to, capacity):
        e1 = self.edge(from_, to, 0, capacity)
        e2 = self.edge(to, from_, 0, 0)
        self.edg.append(e1)
        self.edg.append(e2)
        self.g[from_].append(len(self.edg) - 2)
        self.g[to].append(len(self.edg) - 1)

    def bfs(self):
        for i in range(MAX_SIZE):
            self.visited[i] = 0
            self.dist[i] = 0
        q = deque()
        q.append(self.s)
        self.visited[self.s] = 1
        self.dist[self.s] = 0
        while q:
            v = q.popleft()
            for i in self.g[v]:
                e = self.edg[i]
                nxt = e.to
                if not self.visited[nxt] and e.capacity > e.flow:
                    self.dist[nxt] = self.dist[v] + 1
                    q.append(nxt)
                    self.visited[nxt] = 1
        return self.visited[self.t]

    def dfs(self, x, cp):
        if x == self.t or cp == 0:
            return cp
        flow = 0
        while self.cur[x] < len(self.g[x]):
            y = self.g[x][self.cur[x]]
            e = self.edg[y]
            if self.dist[x] + 1 == self.dist[e.to]:
                minn = min(cp, e.capacity - e.flow)
                newflow = self.dfs(e.to, minn)
                if newflow > 0:
                    e.flow += newflow
                    self.edg[y ^ 1].flow -= newflow
                    flow += newflow
                    cp -= newflow
                    if cp == 0:
                        break
            self.cur[x] += 1
        return flow

    def Dinic(self):
        flow = 0
        while self.bfs():
            self.cur = [0] * MAX_SIZE
            flow += self.dfs(self.s, INF)
        return flow

