from collections import deque

def bfs():
    level = [-1] * (2*tot+2)
    level[st] = 0
    queue = deque([st])
    while queue:
        u = queue.popleft()
        for i, (v, cap, rev) in enumerate(graph[u]):
            if cap > 0 and level[v] < 0:
                level[v] = level[u] + 1
                queue.append(v)
