    INF = 1000000009
    xx = [0, 1, 0, -1]
    yy = [1, 0, -1, 0]

    def bfs(d, sx, sy):
        c = [[False] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                d[i][j] = INF
        q = deque()
        c[sx][sy] = True
        d[sx][sy] = 0
        q.append((sx, sy))
        while q:
            x, y = q.popleft()
            for i in range(4):
                h_x = x + xx[i]
                h_y = y + yy[i]
                if 0 <= h_x < n and 0 <= h_y < n and not c[h_x][h_y] and '0' <= a[h_x][h_y] <= '9':
                    c[h_x][h_y] = True
                    d[h_x][h_y] = d[x][y] + 1
                    q.append((h_x, h_y))

    v = [[0] * n for _ in range(n)]
    bfs(v, sx, sy)

    # Initialize dp array
    max_time = t + 1
    dp = [[[[[False for _ in range(n)] for _ in range(n)] for _ in range(n)] for _ in range(n)] for _ in range(max_time)]
    u = [[[[False for _ in range(n)] for _ in range(n)] for _ in range(n)] for _ in range(n)]

    # Set initial states
    for i in range(n):
