            if '0' <= a[i][j] <= '9':
                dp[0][i][j][i][j] = True

    # Propagate states over time
    for yt in range(t):
        for sx_ in range(n):
            for sy_ in range(n):
                for x in range(n):
                    for y in range(n):
                        if not dp[yt][sx_][sy_][x][y]:
                            continue
                        if v[x][y] <= yt:
                            continue
                        for i in range(4):
                            hx = x + xx[i]
                            hy = y + yy[i]
                            if 0 <= hx < n and 0 <= hy < n and '0' <= a[hx][hy] <= '9':
                                if v[hx][hy] >= yt + 1:
                                    dp[yt + 1][sx_][sy_][hx][hy] = True

    # Mark reachable states
    for yt in range(t + 1):
        for sx_ in range(n):
            for sy_ in range(n):
                for x in range(n):
                    for y in range(n):
