    for x1 in range(n):
        for y1 in range(n):
            for x2 in range(n):
                for y2 in range(n):
                    if not ('0' <= a[x1][y1] <= '9') or not ('0' <= a[x2][y2] <= '9'):
                        continue
                    if not u[x1][y1][x2][y2]:
                        continue
                    g[x1 * n + y1 + 1][n * n + x2 * n + y2 + 1] = INF

    def bfs1():
        for i in range(len(c)):
            c[i] = False
        for i in range(len(p)):
            p[i] = 0
        c[0] = True
        q = deque([0])
        while q:
            x = q.popleft()
            if x == 2 * total_nodes + 1:
                return True
            for h in range(2 * total_nodes + 2):
                if g[x][h]:
                    if not c[h]:
                        c[h] = True
                        p[h] = x
                        q.append(h)
        return False

    # Build residual graph
    while bfs1():
        minu = INF
        i = 2 * total_nodes + 1
        while i:
            minu = min(minu, g[p[i]][i])
            i = p[i]
        i = 2 * total_nodes + 1
        while i:
            g[p[i]][i] -= minu
            g[i][p[i]] += minu
            i = p[i]

    ans = 0
    for i in range(2 * total_nodes + 2):
        ans += g[i][0]
    print(ans)

