import sys
from collections import deque

def isok(r, c, n, ma):
    if 0 < r <= n and 0 < c <= n and ma[r][c] != -1:
        return (r - 1) * n + c
    return -1

def BG(n, ma):
    N = n * n
    mat = [[-1] * (N + 1) for _ in range(N + 1)]
    for r1 in range(1, n + 1):
        for c1 in range(1, n + 1):
            if ma[r1][c1] == -1:
                continue
            p1 = (r1 - 1) * n + c1
            mat[p1][p1] = 0
            for dr, dc in [(0, -1), (0, 1), (-1, 0), (1, 0)]:
                r2, c2 = r1 + dr, c1 + dc
                if 0 < r2 <= n and 0 < c2 <= n and ma[r2][c2] != -1:
                    p2 = (r2 - 1) * n + c2
                    mat[p1][p2] = 1
    return mat

def spfa(n, N, mat, zr, zc):
    dis = [float('inf')] * (N + 1)
    dd = (zr - 1) * n + zc
    dis[dd] = 0
    queue = deque([dd])
    while queue:
        now = queue.popleft()
        for i in range(1, N + 1):
            if mat[now][i] == 1 and dis[i] > dis[now] + 1:
                dis[i] = dis[now] + 1
                queue.append(i)
    return dis

def Floyd(n, N, mat):
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            for z in range(1, N + 1):
                if mat[j][i] != -1 and mat[i][z] != -1:
                    if mat[j][z] == -1 or mat[j][z] > mat[j][i] + mat[i][z]:
                        mat[j][z] = mat[j][i] + mat[i][z]

class Edge:
    def __init__(self, st, ed, flow, next_edge):
        self.st = st
        self.ed = ed
        self.flow = flow
        self.next = next_edge

def add_edge(edges, head, st, ed, flow, E):
    edges.append(Edge(st, ed, flow, head[st]))
    head[st] = E
    E += 1
    edges.append(Edge(ed, st, 0, head[ed]))
    head[ed] = E
    E += 1
    return E

def BF(n, cx, cy, hu, re, ma, zr, zc, t, mat):
    maxn = 200
    maxm = 100000
    inf = 199999999
    E = 0
    head = [-1] * (maxn)
    edges = []
    src = 0
