            ed = edges[i].ed
            if d[ed] == -1 and edges[i].flow > 0:
                d[ed] = d[now] + 1
                if ed == dest:
                    return True
                queue.append(ed)
            i = edges[i].next
    return False

def dinic(n, head, edges, src, dest):
    max_flow = 0
    d = [-1] * (len(head))
    while dinic_bfs(n, head, edges, src, dest, d):
        cur = head[:]
