    def _bfs(self):
        q = deque()
        for i in range(self.n):
            self.d[i] = -1
        self.d[self.src] = 0
        q.append(self.src)
        while q:
            k = q.popleft()
            i = self.head[k]
            while i != -1:
                e = self.e[i]
                if e.f < e.c and self.d[e.v] == -1:
                    self.d[e.v] = self.d[k] + 1
                    q.append(e.v)
                i = e.nx
        return self.d[self.dst] != -1

    def _dfs(self, u, f):
        if u == self.dst:
            return f
        i = self.work[u]
        while i != -1:
            e = self.e[i]
            if e.f < e.c and self.d[e.v] == self.d[u] + 1:
                minf = self._dfs(e.v, min(f, e.c - e.f))
                if minf > 0:
                    e.f += minf
                    self.e[i ^ 1].f -= minf
                    return minf
            i = e.nx
            self.work[u] = i
        return 0

    def maxFlow(self):
        ret = 0
        while self._bfs():
            for i in range(self.n):
                self.work[i] = self.head[i]
            while True:
                delta = self._dfs(self.src, INF)
                if delta == 0:
                    break
                ret += delta
        return ret

def main():
    input_lines = sys.stdin.read().splitlines()
    index = 0
    while index < len(input_lines):
        line = input_lines[index].strip()
        if not line:
            index += 1
            continue
        parts = line.split()
        if len(parts) < 2:
            break
        n, t = map(int, parts)
        index += 1
        dinic = Dinic()
        def S():
            return n * n * 2
        def T():
            return S() + 1
        def N():
            return T() + 1
        smp = [''] * n
        cmp = [''] * n
        work = [[''] * n for _ in range(n)]
        vis = [[0] * n for _ in range(n)]
        dx = [1, 0, -1, 0]
        dy = [0, -1, 0, 1]
        zx, zy = 0, 0

        # Read smp
        for i in range(n):
            smp[i] = input_lines[index]
            index += 1
        # Read cmp
        for i in range(n):
            cmp[i] = input_lines[index]
            index += 1

        # Initialize graph
        dinic.init(N(), S(), T())

        def X(i, j):
            return i * n + j

        def Y(i, j):
            return n * n + i * n + j

        # Add edges from source
        for i in range(n):
            for j in range(n):
                if smp[i][j] > '0' and smp[i][j].isdigit():
                    c = int(smp[i][j])
                    if c > 0:
                        dinic.addEdge(S(), X(i, j), c)
                elif smp[i][j] == 'Z':
                    zx, zy = i, j

        # Add edges to sink
        for i in range(n):
            for j in range(n):
                if cmp[i][j] > '0' and cmp[i][j].isdigit():
                    c = int(cmp[i][j])
                    if c > 0:
                        dinic.addEdge(Y(i, j), T(), c)

        # BFS function
        def bfs(sx, sy):
            for i in range(n):
                for j in range(n):
                    vis[i][j] = 0
            queue = deque()
            queue.append((sx, sy, 0, 0))
            vis[sx][sy] = 1
            queue.append((zx, zy, 0, 1))
            while queue:
                x, y, t_curr, tp = queue.popleft()
                if t_curr == t:
                    break
                if tp == 0 and smp[x][y].isalpha():
                    continue
                for i in range(4):
                    nx, ny = x + dx[i], y + dy[i]
                    if 0 <= nx < n and 0 <= ny < n:
                        if tp == 0 and not vis[nx][ny] and not smp[nx][ny].isalpha():
                            vis[nx][ny] = 1
                            queue.append((nx, ny, t_curr + 1, 0))
                        elif tp == 1 and not smp[nx][ny].isalpha():
                            work[nx][ny] = 'Z'
                            queue.append((nx, ny, t_curr + 1, 1))

        # For each cell with a positive digit in smp, run BFS
        for i in range(n):
            for j in range(n):
                if smp[i][j] > '0' and smp[i][j].isdigit():
                    for xi in range(n):
                        for yi in range(n):
                            if cmp[xi][yi] > '0' and cmp[xi][yi].isdigit():
                                if vis[xi][yi]:
                                    dinic.addEdge(X(i, j), Y(xi, yi), INF)

        # Run max flow
        print(dinic.maxFlow())

if __name__ == "__main__":
    main()

