def geta(x, y, b):
    lower = (b * x) // y
    upper = (b * x + y - 1) // y
    return (lower, upper)

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solve(x, y, n):
    cands = []
    for b in range(1, n + 1):
        ap = geta(x, y, b)
        cands.append((ap[0], b))
        cands.append((ap[1], b))

    def comp(fa, fb):
        a1, b1 = fa
        a2, b2 = fb
        left = abs(x * b1 * b2 - a1 * b2 * y)
        right = abs(x * b1 * b2 - a2 * b1 * y)
        if left < right:
            return -1
        elif left > right:
            return 1
        if b1 < b2:
            return -1
        elif b1 > b2:
            return 1
        if a1 < a2:
            return -1
        elif a1 > a2:
            return 1
        return 0

    cands.sort(key=lambda f: (abs(x * f[1] * f[1] - f[0] * f[1] * y), f[1], f[0]))
    # Since Python's sort doesn't support custom comparator directly, we use key with a tuple
    # but to match the comparator logic exactly, we need to sort with a custom key that reflects the comparator.
    # Alternatively, we can use the 'functools.cmp_to_key' to convert comparator to key.
    from functools import cmp_to_key
    cands.sort(key=cmp_to_key(comp))
    print(f"{cands[0][0]}/{cands[0][1]}")

if __name__ == "__main__":
    x, y, n = map(int, input().split())
    solve(x, y, n)

