	}
	return a;
}
struct dro
{
	long long ch;
	long long zn;
	dro()
	{}
	dro(long long a, long long b)
	{
		ch = a;
		zn = b;
	}
	void operator - (const dro &a)
	{
		ch = ch * a.zn - a.ch * zn;
		zn = zn * a.zn;
	}
	bool operator < (const dro &a) const
	{
		if (ch * a.zn < a.ch * zn)
			return true;
		else
			return false;
	}
	void cok()
	{
		long long j = gcd(ch, zn);
		ch /= j;
		zn /= j;
	}
	void sho()
	{
		cout << ch << "/" << zn;
	}
};

