vector <int> s[7];
INT sum[7];
INT nxt(INT val,INT n){
	if(val*10<=n) return val*10;
	else {
		val++;
		if(val<=n) while(val%10==0) val/=10;
		else {
			val=(val-1)/10+1;
			while(val%10==0) val/=10;
		}
	}
	return val;
}

int L[NN];

void pre(){
	int val=0,len=1;
	int nth=1;
	for(int i=1;i<=1111110;i++){
		s[len].pb(D(nth,val));
		nth++;
		if(len<6) len++,val*=10;
		else {
			val++;
			while(val%10==0) val/=10,len--;
		}
	}

	for(int i=1;i<7;i++){
		sort(s[i].begin(),s[i].end());
		for(int v:s[i]) sum[i]=(sum[i]+v)%mod2;
	}

