#include <cstdio>
#define LL long long
using namespace std;
//tim so chu so cua n
int num(LL n){
   int num = 0;
    while(n){
        n /= 10;
        num++;
    }
    return num; 
}
//tinh so co dang 11...1 lon nhat nhung khong vuot qua n
LL find(LL n){
    int ex = num(n);
    LL cur = 0, ad = 1;
    for(int i = 0; i <= ex-1; i++){
            cur += ad;
            ad *= 10;
    }
    if(cur <= n) return cur;
    return ((cur-1)/10);
}

LL process(LL n){         
    if(n <= 6) return n;
    if(n <= 11) return (13 - n);
    LL less = find(n);
    LL more = less*10+1;
    if(n % less == 0){
        if(n <= more/2 + less) return num(less)*n / less;
        return num(more) + process(more - n);
    }
    else{
        LL _m = (n / less)*less;
        LL res = process(_m) + process(n - _m);
        if(n > more/2) res = min(process(_m) + process(n - _m), num(more) + process(more-n));
        return res;
    }
}
int main(){
    LL n;
    cin>>n;
    cout<<process(n)<<endl;  
    return 0;
}

