MOD = 10**9 + 7

def poww(a, b):
    times = 1
    while b:
        if b & 1:
            times = times * a % MOD
        a = a * a % MOD
        b >>= 1
    return times

def main():
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    P = []
    index = 1
    for _ in range(N):
        row = list(map(int, data[index:index+N]))
        index += N
        P.append(row)

    # Using a dictionary to simulate unordered_map with bitset keys
    id_map = {}
    cnt = 0

    def dfs(x):
        nonlocal cnt
        if x in id_map:
            return id_map[x]
        nd = id_map[x] = cnt
        cnt += 1
        tmp = [0] * N
        for i in range(N):
            for j in range(1 << N):
                tmp[i] |= x[j] << (j | (1 << i))
        for i in range(1 << N):
            tp = list(x)
            for j in range(N):
                if (i >> j) & 1:
                    tp = [tp[k] | tmp[j] for k in range(N)]
            trans[nd][i] = dfs(tp)
        return nd

    # Initialize bitset with only the 0th bit set
    tmp = [0] * (1 << N)
    tmp[0] = 1
    id_map = {}
