import sys

MOD = 1000000007

def powmod(a, b):
    res = 1
    a %= MOD
    while b > 0:
        if b & 1:
            res = (res * a) % MOD
        a = (a * a) % MOD
        b >>= 1
    return res

def bit(n):
    return 1 << n

def bitu128(n):
    return 1 << n

def get_ind(state, what, bfs, ind, SZ, length):
    pos = 0
    for i in range(128):
        pos = (pos * 2 + ((state >> i) & 1)) % SZ
    while True:
        if what[pos] == state:
            return ind[pos]
        if what[pos] == 0:
            what[pos] = state
            bfs.append(state)
            ind[pos] = len(bfs) - 1
            return ind[pos]
        pos += 1
        if pos == SZ:
            pos = 0

def precalc(n):
    N = bit(n)
    fixed_size = [0] * (n + 1)
    for mask in range(N):
        cnt = bin(mask).count('1')
        fixed_size[cnt] |= bitu128(mask)
    SZ = sizes[n]
    what = [0] * SZ
    ind = [0] * SZ
    bfs = []

    # Initialize with empty graph state
    get_ind(1, what, bfs, ind, SZ, 0)
    length = len(bfs)

    next_state = [[0] * length for _ in range(N)]
    match = [0] * length

    for k in range(length):
        state = bfs[k]
        pred_hall = [0] * n
        for mask in range(N):
            if ((state >> mask) & 1):
                for i in range(n):
                    pred_hall[i] |= bitu128(mask | bit(i))
        for mask in range(N):
            nxt = state
            for i in range(n):
                if (mask & (1 << i)):
                    nxt |= pred_hall[i]
            next_state[mask][k] = get_ind(nxt, what, bfs, ind, SZ, length)
        for i in range(n, -1, -1):
            if (state & fixed_size[i]) != 0:
                match[k] = i
                break
    return bfs, next_state, match

def expectedMaximumMatching(n, m, p, bfs, next_state, match):
    length = len(bfs)
    prev = [0] * length
    prev[0] = 1
    for k in range(1, length):
        prev[k] = 0
    N = bit(n)

    for j in range(m):
        cur = [0] * length
        for mask in range(N):
            prob = 1
            for i in range(n):
                if (mask & (1 << i)):
                    prob = (prob * p[i][j]) % MOD
                else:
                    prob = (prob * (MOD + 1 - p[i][j])) % MOD
            for k in range(length):
                cur[next_state[mask][k]] = (cur[next_state[mask][k]] + prob * prev[k]) % MOD
        prev = cur

    ans = 0
    for k in range(length):
        if match[k] == n:
            ans = (ans + prev[k]) % MOD
    return ans

