    p = 1000000007
    def fpm(a, b):
        c = 1
        while b:
            if b & 1:
                c = c * a % p
            a = a * a % p
            b >>= 1
        return c

    i100 = fpm(100, p - 2)

    for i in range(n):
        for j in range(n):
            a[i][j] = a[i][j] * i100 % p

    # Initialize f array
    f = [[1] * (1 << n) for _ in range(n)]
    for i in range(n):
        for j in range(1 << n):
            for k in range(n):
                if (j & (1 << k)) != 0:
                    f[i][j] = f[i][j] * a[k][i] % p
                else:
                    f[i][j] = f[i][j] * (p + 1 - a[k][i]) % p

    # Initialize is array
    is_arr = [0] * (1 << n)
    for i in range(n):
        is_arr[1 << i] = i

    # Define the bitset class
    class BitSet:
        def __init__(self):
            self.a = 0
            self.b = 0

        def set(self, x):
            if x < 64:
                self.a |= 1 << x
            else:
                self.b |= 1 << (x - 64)

        def reset(self):
            self.a = 0
            self.b = 0

        def __ior__(self, other):
            self.a |= other.a
            self.b |= other.b
            return self

        def __eq__(self, other):
            return self.a == other.a and self.b == other.b

        def __getitem__(self, index):
            if index < 64:
                return (self.a & (1 << index)) != 0
            else:
                return (self.b & (1 << (index - 64))) != 0

        def copy(self):
            new_bitset = BitSet()
            new_bitset.a = self.a
            new_bitset.b = self.b
            return new_bitset

    # Initialize the memoization dictionary
    from collections import defaultdict
    st = [defaultdict(lambda: -1) for _ in range(n)]

    # Initialize the maximum bitset
    mx = BitSet()
    for i in range(1 << n):
        mx.set(i)

    # Recursive DFS with memoization
