import sys
import math

class Modular:
    def __init__(self, v=0):
        self.val = v % 1000000007

    def __int__(self):
        return self.val

    def __eq__(self, b):
        return self.val == b.val

    def __ne__(self, b):
        return self.val != b.val

    def __lt__(self, b):
        return self.val < b.val

    def __gt__(self, b):
        return self.val > b.val

    def __le__(self, b):
        return self.val <= b.val

    def __ge__(self, b):
        return self.val >= b.val

    def __neg__(self):
        return Modular(0) if self.val == 0 else Modular(1000000007 - self.val)

    def __iadd__(self, m):
        self.val += m.val
        if self.val >= 1000000007:
            self.val -= 1000000007
        return self

    def __isub__(self, m):
        self.val -= m.val
        if self.val < 0:
            self.val += 1000000007
        return self

    def __imul__(self, m):
        if isinstance(m, Modular):
            self.val = (self.val * m.val) % 1000000007
        else:
            self.val = (self.val * m) % 1000000007
        return self

    def pow(self, p):
        result = Modular(1)
        base = Modular(self.val)
        while p:
            if p & 1:
                result *= base
            base *= base
            p >>= 1
        return result

    def inv(self):
        # Fermat's little theorem for modular inverse
        return self.pow(1000000007 - 2)

    def __itruediv__(self, m):
        return self.__imul__(m.inv())

    def __add__(self, b):
        res = Modular(self.val)
        res += b
        return res

    def __sub__(self, b):
        res = Modular(self.val)
        res -= b
        return res

    def __mul__(self, b):
        res = Modular(self.val)
        res *= b
        return res

    def __truediv__(self, b):
        res = Modular(self.val)
        res /= b
        return res

def main():
    input = sys.stdin.read
    data = input().split()
    number = int(data[0])
