    global dfn
    if s in name:
        return name[s]
    ret = dfn
    name[s] = ret
    dfn += 1
    for i in range(1 << n):
        t = s
        for j in range(1 << n):
            if not (t & (1 << j)):
                for k in range(1 << n):
