        for (int i = 0; i <= d; i++) {
            for (int j = 0; j <= d; j++) {
                f[i][j] = 0;
            }
        }
    }

    matrix operator*(const matrix& oth) const {
        matrix ans;
        for (int i = 0; i <= d; i++) {
            for (int j = 0; j <= d; j++) {
                for (int k = 0; k <= d; k++) {
                    (ans.f[i][j] += f[i][k] * oth.f[k][j]) %= MOD;
                }
            }
        }
        return ans;
    }
} bas[N];

matrix rotate(int u) {
    (u += d) %= d;
    matrix ans;
    for (int i = 0; i < d; i++) {
        ans.f[i][(i + u) % d] = 1;
    }
    ans.f[d][d] = 1;
    return ans;
}

