    return r

def addmod(a, val, p=10**9+7):
    a += val
    if a >= p:
        a -= p
    return a

def submod(a, val, p=10**9+7):
    a -= val
    if a < 0:
        a += p
    return a

def mult(a, b, p=10**9+7):
    return (a * b) % p

def inv(a, p=10**9+7):
    return fpow(a, p - 2, p)

def transform(a, n, p, invert):
    k = int(math.log2(n))
    for i in range(k):
        for msk in range(n):
            if bit(msk, i):
                pmsk = msk ^ (1 << i)
                if not invert:
                    a[msk] = addmod(a[msk], a[pmsk], p)
                else:
                    a[msk] = submod(a[msk], a[pmsk], p)

def pow_convol(a, k, p):
    n = len(a)
    if k == 1:
        return a
    elif k & 1:
        r = pow_convol(a, k - 1, p)
        res = [0] * n
        for i in range(n):
            for j in range(n - i):
                res[i + j] = (res[i + j] + r[i] * a[j]) % p
        return res
    else:
        r = pow_convol(a, k >> 1, p)
        res = [0] * n
        for i in range(n):
            for j in range(n - i):
                res[i + j] = (res[i + j] + r[i] * r[j]) % p
        return res

def subset_pow_convol(a, k, p):
    logn = 19
    fa = [[0] * (1 << logn) for _ in range(logn)]
    fb = [[0] * (1 << logn) for _ in range(logn)]
    fc = [[0] * (1 << logn) for _ in range(logn)]
    n = len(a)
    while n != (n & -n):
        n += n & -n
    res = [0] * n
    for i in range(logn):
        for j in range(n):
            if bitcount(j) == i:
                fa[i][j] = a[j] if j < len(a) else 0
            else:
                fa[i][j] = 0
            fc[i][j] = 0
        transform(fa[i], n, p, False)
    for i in range(n):
        va = [0] * logn
        for j in range(logn):
            va[j] = fa[j][i]
        va = pow_convol(va, k, p)
        for j in range(logn):
            fc[j][i] = va[j]
    for i in range(logn):
        transform(fc[i], n, p, True)
        for j in range(n):
            if bitcount(j) == i:
                res[j] = fc[i][j]
    return res

def solve():
    input_data = sys.stdin.read().strip().split()
    n, k, p = map(int, input_data[:3])
