import sys

def qpow(a, b, mod):
    res = 1
    tp = a
    while b:
        if b & 1:
            res = (res * tp) % mod
        tp = (tp * tp) % mod
        b >>= 1
    return res

def cal(a, b, fac, inv, mod):
    return (((fac[a] * inv[b]) % mod) * inv[a - b]) % mod

def calc(n, k, fac, inv, mod):
    dp = [[0] * (n + 1) for _ in range(18)]
    for i in range(1, n + 1):
        dp[1][i] = inv[i]
    ans = (dp[1][n] * cal(k, 1, fac, inv, mod)) % mod
    t = min(17, k)
    for i in range(2, t + 1):
        for j in range(n, 0, -1):
            l = j
            while l:
                for sub in range(l, 0, -1):
                    if (l & sub) == sub:
                        dp[i][j] += dp[i - 1][j ^ sub] * inv[sub]
                        if dp[i][j] > 1 << 64:
                            dp[i][j] %= mod
                l = (l - 1) & j
        ans += dp[i][n] * cal(k, i, fac, inv, mod)
        ans %= mod
    fac[0] = 1
    for i in range(1, n + 1):
        fac[i] = (fac[i - 1] * i) % mod
    inv[n] = qpow(fac[n], mod - 2, mod)
    for i in range(n - 1, -1, -1):
        inv[i] = (inv[i + 1] * (i + 1)) % mod
    ans = (ans * fac[n]) % mod
    return ans

def main():
    input_data = sys.stdin.read().strip().split()
    n, k, mod = map(int, input_data)
    ans = qpow(k, n, mod)
    if n & 1:
        print(ans)
        return
    # Prepare factorials and inverses
    fac = [0] * (n + 1)
    inv = [0] * (n + 1)
    for i in range(1, n + 1):
        fac[i] = (fac[i - 1] * i) % mod
    inv[n] = qpow(fac[n], mod - 2, mod)
    for i in range(n - 1, -1, -1):
        inv[i] = (inv[i + 1] * (i + 1)) % mod
    def calc_value():
        return cal(n, 1, fac, inv, mod)
    ans = (ans - calc_value() + mod) % mod
    print(ans)

if __name__ == "__main__":
    main()

