def pwr(x, y, Mo):
    z = 1
    while y:
        if y & 1:
            z = (z * x) % Mo
        y >>= 1
        x = (x * x) % Mo
    return z

def inc(a, y, Mo):
    a[0] = a[0] + y
    if a[0] >= Mo:
        a[0] -= Mo

def dec(a, y, Mo):
    a[0] = a[0] - y
    if a[0] < 0:
        a[0] += Mo

def FWT(a, length, Mo):
    i = 1
    while i < length:
        j = 0
        while j < length:
            for k in range(i):
                inc([a[j + k + i]], a[j + k], Mo)
            j += i << 1
        i <<= 1

def IFWT(a, length, Mo):
    i = 1
    while i < length:
        j = 0
        while j < length:
            for k in range(i):
                dec([a[j + k + i]], a[j + k], Mo)
            j += i << 1
        i <<= 1

def get_ln(h, n, Mo, inv):
    p = [0] * (n + 1)
    for i in range(1, n + 1):
        p[i] = h[i] * i % Mo
        for j in range(1, i):
            p[i] -= p[j] * h[i - j] % Mo * j
        p[i] %= Mo
        p[i] = p[i] * inv[i] % Mo
    for i in range(n + 1):
        h[i] = (p[i] + Mo) % Mo

