	modint& operator*=(const modint& a) { v=v*a.v%mo; return *this;}
	modint& operator/=(const modint& a) { assert(a.v!=0); *this*=pow(a); return *this;}
	modint operator+(const modint& a) const { modint res(*this); return res+=a;}
	modint operator-(const modint& a) const { modint res(*this); return res-=a;}
	modint operator*(const modint& a) const { modint res(*this); return res*=a;}
	modint operator/(const modint& a) const { modint res(*this); return res/=a;}
