  }
}

int c[maxn][maxn];

struct T {
  int cnt, sum;

  T(): cnt(0), sum(0) {}

  T(int x): cnt(x), sum(0) {}

  T(int c, int s): cnt(c), sum(s) {}

  T operator * (const T &t) const {
    int s = mul(cnt, t.sum);
    add(s, mul(sum, t.cnt));
    return T(mul(cnt, t.cnt), s);
  }

  T operator + (const T &t) const {
    int c = cnt;
    add(c, t.cnt);
    int s = sum;
    add(s, t.sum);
    return T(c, s);
  }
};

T dp[maxn];
