def spow(a, b, M):
    r = 1
    while b:
        if b % 2:
            r = r * a % M
        a = a * a % M
        b //= 2
    return r

def Inv(a, M):
    b = M - 2
    r = 1
    while b:
        if b % 2:
            r = r * a % M
        a = a * a % M
        b //= 2
    return r

