		long long sum2 = C[v2][r];
		res += solve(x, y + cur1 * sum2, v1 - 1, v2);
	}
	if (c != 'A')
	{
		long long sum1 = C[v1][r];
		long long cur2 = C[v2][r] - C[v2 - 1][r];
		res += solve(x + sum1 * cur2, y, v1, v2 - 1);
	}
	return res;
}
