import sys
import math
from bisect import bisect_left

def main():
    input = sys.stdin.read
    data = input().split()
    R, C = map(int, data[0:2])
    p = data[2]
    n = R + C

    # Precompute combinations
    Comb = [[0]*63 for _ in range(63)]
    for i in range(63):
        Comb[i][0] = 1
        for j in range(1, i+1):
            Comb[i][j] = Comb[i-1][j-1] + Comb[i-1][j]

    TT = Comb[n*2][R*2]

    # Initialize A and B
    A = [[0]*(n+1) for _ in range(n+1)]
    B = [[0]*(n+1) for _ in range(n+1)]
    for i in range(1, n+1):
        for j in range(1, n+1):
            if i:
                A[i][j] = Comb[i-1][R-1] * (Comb[n*2 - i][R] - Comb[j][R])
            if j:
                B[i][j] = Comb[j-1][R-1] * (Comb[n*2 - j][R] - Comb[i][R])

    # Initialize CC
    CC = [[0]*(n+1) for _ in range(n+1)]
    CC[0][0] = 1
    for i in range(n+1):
        for j in range(n+1):
            if i != n and p[i + j] != 'B':
                CC[i+1][j] += CC[i][j]
            if j != n and p[i + j] != 'A':
                CC[i][j+1] += CC[i][j]

    # Initialize P and Q
    P = [[[] for _ in range(2)] for _ in range(n+1)]
    Q = [[[] for _ in range(2)] for _ in range(n+1)]

    def Put(x, y, g, c1, c2, ck):
        if x + y == R + n:
            P[x][ck].append((g, c1))
            if c2:
                Q[x][ck].append((g, c2))
            return
        if x + 1 <= R + n:
            Put(x + 1, y, g + (0 if ck else A[x+1][y]), c1, c2 if p[x + y] != 'B' else 0, ck)
        if y + 1 <= R + n:
            Put(x, y + 1, g + (B[x][y+1] if ck else 0), c1, c2 if p[x + y] != 'A' else 0, ck)

    def Make(P_list):
        if not P_list:
            return
        P_list.sort()
        new_list = []
        s = 0
        for i in range(len(P_list)):
            s += P_list[i][1]
            if i == len(P_list) - 1 or P_list[i][0] != P_list[i+1][0]:
                new_list.append((P_list[i][0], s))
        P_list.clear()
        P_list.extend(new_list)

    def Calc1(x, y, g, ck):
        if x + y == R + n:
            P_x = P[x][ck]
            if not P_x:
                return
            t = bisect_left(P_x, ( (TT+1)//2 - g, 0))
            if t != len(P_x) and P_x[t][1] > 0:
                tp = (P_x[t][0] + g) * 2 - TT
                if tp < 0:
                    tp = -tp
                if MM > tp:
                    nonlocal MM
                    MM = tp
            if t > 0 and P_x[t-1][1] > 0:
                tp = (P_x[t-1][0] + g) * 2 - TT
                if tp < 0:
                    tp = -tp
                if MM > tp:
                    MM = tp
            return
        if x - 1 >= 0:
            Calc1(x - 1, y, g + (0 if ck else A[x][y]), ck)
        if y - 1 >= 0:
            Calc1(x, y - 1, g + (B[x][y] if ck else 0), ck)

    def Calc2(x, y, g, ck):
        if x + y == R + n:
            Q_x = Q[x][ck]
            t = bisect_left(Q_x, ( (TT+1)//2 - g, 0))
            if t != len(Q_x) and Q_x[t][1] > 0:
                tp = (Q_x[t][0] + g) * 2 - TT
                if tp < 0:
                    tp = -tp
                if MM == tp:
                    nonlocal Res
                    Res += Q_x[t][1]
            if t > 0 and Q_x[t-1][1] > 0:
                tp = (Q_x[t-1][0] + g) * 2 - TT
                if tp < 0:
                    tp = -tp
                if MM == tp:
                    Res += Q_x[t-1][1]
            return
        if p[x + y - 1] != 'B' and x - 1 >= 0:
            Calc2(x - 1, y, g + (0 if ck else A[x][y]), ck)
        if p[x + y - 1] != 'A' and y - 1 >= 0:
            Calc2(x, y - 1, g + (B[x][y] if ck else 0), ck)

    # Generate P and Q
    for i in range(R, n+1):
        if p[i + R - 1] != 'B':
            Put(R, i, A[R][i], Comb[i+R-1][R-1], CC[R-1][i], 0)
        if p[i + R - 1] != 'A':
            Put(i, R, B[i][R], Comb[i+R-1][R-1], CC[i][R-1], 1)

    for i in range(R, n+1):
        for j in range(2):
            Make(P[i][j])
            Make(Q[i][j])

    global MM, Res
    MM = TT + 1
    Res = 0
    Calc1(n, n, 0, 0)
    Calc1(n, n, 0, 1)
    Calc2(n, n, 0, 0)
    Calc2(n, n, 0, 1)

    print(Res)

if __name__ == "__main__":
    main()

